"""Allocated-range reporting for sink files.

The transfer layer resumes an interrupted download by asking which parts of a
sink are already on disk.  That question is only answerable by the file system:
``FSCTL_QUERY_ALLOCATED_RANGES`` returns the byte ranges of the file that are
really backed by clusters, and everything the query does not mention is a hole
that still needs data.
"""

import os

from . import _winapi
from ._common import check_sparse_target, classify, normalise_ranges
from .errors import WSParseError


def _ranges_windows(path):
    try:
        handle = _winapi.open_handle(path, write=False, create=False)
    except OSError as exc:
        raise classify(exc, path) from exc

    with handle:
        try:
            size = _winapi.file_size(handle)
            if size <= 0:
                return []
            found = _winapi.query_allocated_ranges(handle, size)
        except OSError as exc:
            raise classify(
                exc,
                path,
                "the volume or object does not support allocated-range queries",
            ) from exc
    return normalise_ranges(found, size)


def _ranges_posix(path):
    from . import _posix

    try:
        size = os.path.getsize(path)
        if size <= 0:
            return []
        found = _posix.allocated_ranges(path, size)
    except OSError as exc:
        raise classify(exc, path) from exc
    return normalise_ranges(found, size)


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is already allocated is on disk, everything else
    is a hole that still needs data.  The list is ordered by ``offset`` and the
    ranges never overlap.  Every range lies inside the file's logical length.

    A file that is one big hole reports an empty list.  A dense file reports a
    single range covering its whole length.

    Raises :class:`WSParseError` with ``kind == "unsupported"`` when the target
    cannot answer the query (a directory, or a volume without sparse-file
    support), and ``kind == "os"`` for any other operating-system failure.
    """
    path = os.fspath(path)
    check_sparse_target(path, must_exist=True)

    if _winapi.is_windows():
        return _ranges_windows(path)
    return _ranges_posix(path)

